ion\":\"Maximum AC side output power rating of the unit. Not to be confused with base_power. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ApparentPower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"reactive_power\":{\"description\":\"Initial reactive power set point of the unit. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"reactive_power_limits\":{\"description\":\"Minimum and maximum reactive power limits. Set to `null` if not applicable. in psy5 a required param with an option to be nothing Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"time_limits\":{\"description\":\"Minimum up and minimum down time limits. Units: min.\",\"properties\":{\"down\":{\"title\":\"Down\",\"type\":\"number\"},\"up\":{\"title\":\"Up\",\"type\":\"number\"}},\"required\":[\"up\",\"down\"],\"title\":\"UpDown\",\"type\":\"object\",\"x-unit\":\"min\"},\"travel_time\":{\"default\":null,\"description\":\"Downstream (from reservoir into turbine) travel time. Set to `null` if not applicable. Units: min.\",\"type\":[\"number\",\"null\"],\"x-unit\":\"min\"},\"turbine_type\":{\"default\":\"UNKNOWN\",\"description\":\"Type of the turbine.\",\"enum\":[\"UNKNOWN\",\"PELTON\",\"FRANCIS\",\"KAPLAN\",\"TURGO\",\"CROSSFLOW\",\"BULB\",\"DERIAZ\",\"PROPELLER\",\"OTHER\"],\"type\":\"string\"}},\"required\":[\"id\",\"name\",\"available\",\"bus\",\"active_power\",\"reactive_power\",\"rati