ntity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"base_power\":{\"description\":\"Base power of the unit for per unitization. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"bus\":{\"description\":\"ID of the bus that this component is connected to.\",\"type\":\"integer\"},\"dynamic_injector\":{\"description\":\"ID of the corresponding dynamic injection device, if any.\",\"type\":[\"integer\",\"null\"]},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"max_active_power\":{\"description\":\"Maximum active power that this load can demand. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"motor_technology\":{\"default\":\"UNDETERMINED\",\"description\":\"AC Motor type.\",\"enum\":[\"INDUCTION\",\"SYNCHRONOUS\",\"UNDETERMINED\"],\"type\":\"string\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `MotorLoad`) must have unique names, but components of different types (e.g., `MotorLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"rating\":{\"description\":\"Maximum AC side output power rating of the unit. Not to be confused with base_power. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ApparentPower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"reactive_power\":{\"description\":\"Initial steady-state reactive power demand. A positive value indicates reactive power consumption. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"reactive_power_limits\":{\"description\":\"Minimum and maximum reactive power limits. Set to `null` if not applicable. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}}},\"required\":[\"id\",\"name\",\"available\",\"bus\",\"active_power\",\"reactive_power\",\"base_power\",\"power_units\",\"rating\",\"max_active_power\"],\"title\":\"MotorLoad\",\"type\":\"object\"},\"OfflineReserve\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A non-spinning reserve product from devices not currently synchronized with the system but able to come online quickly after an unexpected contingency. Upward only, so unlike `OnlineReserve` there is no reserve direction. The procurement requirement is static unless a `requirement` time series is attached, in which case `requirement` is the scaling factor.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"deployed_fraction\":{\"default\":0.0,\"description\":\"Fraction of service procurement that is assumed to be actually deployed. Most commonly, this is assumed to be either 0.0 or 1.0.\",\"type\":\"number\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"max_output_fraction\":{\"default\":1.0,\"description\":\"The maximum fraction of each device's output that can be assigned to the service.\",\"type\":\"number\"},\"max_participation_factor\":{\"default\":1.0,\"description\":\"The maximum portion [0, 1.0] of the reserve that can be contributed per device.\",\"type\":\"number\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"requirement\":{\"default\":0.0,\"description\":\"The value of required reserves. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"},\"sustained_time\":{\"default\":60.0,\"description\":\"The time reserve contribution must be sustained at a specified level. Units: min.\",\"type\":\"number\",\"x-unit\":\"min\"},\"time_frame\":{\"description\":\"The saturation time frame to provide reserve contribution. Units: min.\",\"type\":\"number\",\"x-unit\":\"min\"},\"variable\":{\"description\":\"Operating reserve demand curve, either static or time-series-backed. Time series values are carried via `time_series_associations` in the sidecar, never inline. Omit when the reserve has no demand curve.\",\"properties\":{\"power_units\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/UnitSystem\",\"default\":\"NATURAL_UNITS\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/ValueCurve\"},\"variable_cost_type\":{\"const\":\"COST\",\"default\":\"COST\",\"type\":\"string\"},\"vom_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/InputOutputCurve\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}}}},\"required\":[\"value_curve\",\"power_units\",\"vom_cost\",\"variable_cost_type\"],\"title\":\"CostCurve\",\"type\":\"object\"}},\"required\":[\"id\",\"name\",\"available\",\"time_frame\"],\"title\":\"OfflineReserve\",\"type\":\"object\"},\"OnlineReserve\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A reserve product provided by devices already synchronized with the system. The procurement requirement is static unless a `requirement` time series is attached, in which case `requirement` is the scaling factor. Attach an Operating Reserve Demand Curve through `variable` to price the requirement rather than enforce it; omit `variable` when the reserve has no demand curve.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"deployed_fraction\":{\"default\":0.0,\"description\":\"Fraction of service procurement that is assumed to be actually deployed. Most commonly, this is assumed to be either 0.0 or 1.0.\",\"type\":\"number\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"max_output_fraction\":{\"default\":1.0,\"description\":\"The maximum fraction of each device's output that can be assigned to the service.\",\"type\":\"number\"},\"max_participation_factor\":{\"default\":1.0,\"description\":\"The maximum portion [0, 1.0] of the reserve that can be contributed per device.\",\"type\":\"number\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"requirement\":{\"default\":0.0,\"description\":\"The value of required reserves. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"},\"reserve_direction\":{\"description\":\"Whether the reserve is an upward, downward, or symmetric reserve product.\",\"enum\":[\"UP\",\"DOWN\",\"SYMMETRIC\"],\"title\":\"ReserveDirection\",\"type\":\"string\"},\"sustained_time\":{\"default\":60.0,\"description\":\"The time reserve contribution must be sustained at a specified level. Units: min.\",\"type\":\"number\",\"x-unit\":\"min\"},\"time_frame\":{\"description\":\"The saturation time frame to provide reserve contribution. Units: min.\",\"type\":\"number\",\"x-unit\":\"min\"},\"variable\":{\"description\":\"Operating reserve demand curve, either static or time-series-backed. Time series values are carried via `time_series_associations` in the sidecar, never inline. Omit when the reserve has no demand curve.\",\"properties\":{\"power_units\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/UnitSystem\",\"default\":\"NATURAL_UNITS\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/ValueCurve\"},\"variable_cost_type\":{\"const\":\"COST\",\"default\":\"COST\",\"type\":\"string\"},\"vom_cost\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/InputOutputCurve\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}}}},\"required\":[\"value_curve\",\"power_units\",\"vom_cost\",\"variable_cost_type\"],\"title\":\"CostCurve\",\"type\":\"object\"}},\"required\":[\"id\",\"name\",\"available\",\"time_frame\",\"reserve_direction\"],\"title\":\"OnlineReserve\",\"type\":\"object\"},\"OperationalStates\":{\"description\":\"The running on/off lifecycle of an in-service committable unit, mutually exclusive. OFFLINE: shut down and not synchronized. STARTUP: in its start-up sequence. ONLINE: synchronized and able to produce. SHUTDOWN: in its shut-down sequence. Availability is not one of these values: a unit on outage is `available = false`; an OFFLINE unit with `available = true` is in service and eligible for re-commitment and off-line ancillary services.\",\"enum\":[\"OFFLINE\",\"STARTUP\",\"ONLINE\",\"SHUTDOWN\"],\"title\":\"OperationalStates\",\"type\":\"string\"},\"PiecewiseLinearData\":{\"description\":\"Data for a piecewise linear function defined by (x, y) points and interpolated linearly between consecutive ones. The y values are absolute values at each x, not per-segment slopes; use `PiecewiseStepData` when the data gives per-segment rates. Points run in ascending x order, and two of them define one segment.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_LINEAR\",\"default\":\"PIECEWISE_LINEAR\",\"type\":\"string\"},\"points\":{\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/XY_Coords\"},\"type\":\"array\"}},\"required\":[\"points\",\"function_type\"],\"title\":\"PiecewiseLinearData\",\"type\":\"object\"},\"PiecewiseStepData\":{\"description\":\"Data for a step function, constant on each segment, defined by the x coordinates of the segment endpoints and one y value per segment. The y values are per-segment rates, not absolute values; use `PiecewiseLinearData` when the data gives a value at each point. `x_coords` ascends and holds at least two entries, and `y_coords` holds exactly one fewer.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_STEP\",\"default\":\"PIECEWISE_STEP\",\"type\":\"string\"},\"x_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"},\"y_coords\":{\"items\":{\"type\":\"number\"},\"type\":\"array\"}},\"required\":[\"x_coords\",\"y_coords\",\"function_type\"],\"title\":\"PiecewiseStepData\",\"type\":\"object\"},\"PlannedOutage\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Supplemental attribute describing outages that are scheduled in advance, naming the time series that carries the schedule.\",\"properties\":{\"id\":{\"type\":\"integer\"},\"monitored_components\":{\"default\":[],\"description\":\"IDs of devices whose post-contingency state should be modeled when this outage occurs. Empty by default; semantics of an empty list are decided by the downstream consumer.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\",\"uniqueItems\":true},\"outage_schedule\":{\"type\":\"string\"}},\"required\":[\"id\",\"outage_schedule\"],\"title\":\"PlannedOutage\",\"type\":\"object\"},\"PlantAssociation\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Association between a power plant supplemental attribute and a generating unit, identifying the group the unit belongs to within the plant. Covers 1-to-n cases: ThermalPowerPlant shafts, HydroPowerPlant penstocks, RenewablePowerPlant PCCs, and CombinedCycleFractional exclusion groups. The semantics of group_index are determined by the parent plant's type.\",\"properties\":{\"entity_id\":{\"description\":\"ID of the generating unit (entity) participating in the plant\",\"type\":\"integer\"},\"group_index\":{\"description\":\"Group number within the plant (shaft, penstock, PCC, or exclusion group, depending on the parent plant's type)\",\"type\":\"integer\"},\"plant_id\":{\"description\":\"ID of the parent plant supplemental attribute\",\"type\":\"integer\"}},\"required\":[\"plant_id\",\"entity_id\",\"group_index\"],\"title\":\"PlantAssociation\",\"type\":\"object\"},\"PointToPointBid\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A priced point-to-point spread bid (e.g. an up-to-congestion or PTP obligation bid): a willingness-to-pay curve on the price spread between two locations. Clears as a withdrawal at the source terminal and an injection at the sink terminal.\",\"properties\":{\"available\":{\"description\":\"Indicator of whether the bid is available for market clearing (`true`) or not (`false`).\",\"type\":\"boolean\"},\"from_id\":{\"description\":\"ID of the source terminal (withdrawal side), resolved through the entity registry: a topology record or a trading hub.\",\"type\":\"integer\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"linked_crr\":{\"description\":\"Identifier of a linked congestion-right instrument, when the market couples the bid to one.\",\"type\":[\"string\",\"null\"]},\"max_active_power\":{\"description\":\"MW envelope for the bid. Units: MW.\",\"type\":\"number\",\"x-unit\":\"MW\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"price_limits\":{\"description\":\"Tariff bid-price bounds on the spread. Units: USD/MWh.\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-unit\":\"USD/MWh\"},\"spread_bid\":{\"description\":\"Willingness-to-pay curve on the to-minus-from price spread, as an offer-curve operating cost (incremental side only).\",\"discriminator\":{\"mapping\":{\"MARKET_BID\":\"#/components/schemas/MarketBidCost\",\"MARKET_BID_TIME_SERIES\":\"#/components/schemas/MarketBidTimeSeriesCost\"},\"propertyName\":\"cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/MarketBidCost\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/MarketBidTimeSeriesCost\"}]},\"to_id\":{\"description\":\"ID of the sink terminal (injection side), resolved through the entity registry: a topology record or a trading hub; must differ from `from_id`.\",\"type\":\"integer\"}},\"required\":[\"id\",\"name\",\"available\",\"from_id\",\"to_id\",\"max_active_power\",\"spread_bid\",\"price_limits\"],\"title\":\"PointToPointBid\",\"type\":\"object\"},\"PowerLoad\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A static power load, most commonly used for operational models such as power flow and operational optimizations.\\n\\nThis load consumes a set amount of power (set by `active_power` for a power flow simulation or a `max_active_power` time series for an operational simulation). For loads that can be compensated for load interruptions through demand response programs, see `InterruptiblePowerLoad`. For voltage-dependent loads used in dynamics modeling, see `StandardLoad`.\",\"properties\":{\"active_power\":{\"description\":\"Initial steady-state active power demand. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"base_power\":{\"description\":\"Base power of the unit for per unitization. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"bus\":{\"description\":\"ID of the bus that this component is connected to.\",\"type\":\"integer\"},\"conformity\":{\"default\":\"UNDEFINED\",\"description\":\"Indicates whether the specified load is conforming or non-conforming.\",\"enum\":[\"NON_CONFORMING\",\"CONFORMING\",\"UNDEFINED\"],\"title\":\"LoadConformity\",\"type\":\"string\"},\"dynamic_injector\":{\"description\":\"ID of the corresponding dynamic injection device, if any.\",\"type\":[\"integer\",\"null\"]},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"max_active_power\":{\"description\":\"Maximum active power that this load can demand. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"max_reactive_power\":{\"description\":\"Maximum reactive power that this load can demand. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"reactive_power\":{\"description\":\"Initial steady-state reactive power demand. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}}},\"required\":[\"id\",\"name\",\"available\",\"bus\",\"active_power\",\"reactive_power\",\"base_power\",\"power_units\",\"max_active_power\",\"max_reactive_power\"],\"title\":\"PowerLoad\",\"type\":\"object\"},\"ProductionVariableCostCurve\":{\"description\":\"Variable production cost of a device, selected by `variable_cost_type` between a curve denominated directly in currency (`COST`) and one denominated in fuel with a separate fuel price (`FUEL`).\",\"discriminator\":{\"mapping\":{\"COST\":\"#/components/schemas/CostCurve\",\"FUEL\":\"#/components/schemas/FuelCurve\"},\"propertyName\":\"variable_cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/CostCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/FuelCurve\"}],\"title\":\"ProductionVariableCostCurve\",\"type\":\"object\"},\"QuadraticFunctionData\":{\"description\":\"Data for a quadratic function `f(x) = quadratic_term * x^2 + proportional_term * x + constant_term`. A non-negative `quadratic_term` makes the function convex.\",\"properties\":{\"constant_term\":{\"type\":\"number\"},\"function_type\":{\"const\":\"QUADRATIC\",\"default\":\"QUADRATIC\",\"type\":\"string\"},\"proportional_term\":{\"type\":\"number\"},\"quadratic_term\":{\"type\":\"number\"}},\"required\":[\"quadratic_term\",\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"QuadraticFunctionData\",\"type\":\"object\"},\"RenewableDispatch\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A renewable (e.g., wind or solar) generator whose output can be curtailed to satisfy power system constraints.\\n\\nThese generators can also participate in reserves markets, including upwards reserves by proactively curtailing some available power (based on its `max_active_power` time series). Example uses include: a utility-scale wind or solar generator whose PPA allows curtailment. For non-curtailable or must-take renewables, see `RenewableNonDispatch`.\\n\\nRenewable generators do not have a `max_active_power` parameter, which is instead calculated when calling `get_max_active_power()`.\",\"properties\":{\"active_power\":{\"description\":\"Initial active power set point of the unit. For power flow, this is the steady state operating point of the system. For production cost modeling, this may or may not be used as the initial starting point for the solver, depending on the solver used. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"base_power\":{\"description\":\"Base power of the unit for per unitization. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"bus\":{\"description\":\"ID of the bus that this component is connected to.\",\"type\":\"integer\"},\"dynamic_injector\":{\"description\":\"ID of the corresponding dynamic injection device, if any.\",\"type\":[\"integer\",\"null\"]},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"operation_cost\":{\"description\":\"Operating cost of generation. or MarketBidCost\",\"discriminator\":{\"mapping\":{\"IMPORT_EXPORT_TIME_SERIES\":\"#/components/schemas/ImportExportTimeSeriesCost\",\"MARKET_BID\":\"#/components/schemas/MarketBidCost\",\"MARKET_BID_TIME_SERIES\":\"#/components/schemas/MarketBidTimeSeriesCost\",\"RENEWABLE\":\"#/components/schemas/RenewableGenerationCost\"},\"propertyName\":\"cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/RenewableGenerationCost\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/MarketBidCost\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/MarketBidTimeSeriesCost\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1