onstant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}},\"variable_cost_type\":\"COST\",\"vom_cost\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}}},\"import_offer_curves\":{\"value_curve\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}},\"variable_cost_type\":\"COST\",\"vom_cost\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}}}},\"description\":\"Cost of importing and exporting power at the source. or MarketBidCost\",\"discriminator\":{\"mapping\":{\"IMPORTEXPORT\":\"#/components/schemas/ImportExportCost\",\"IMPORT_EXPORT_TIME_SERIES\":\"#/components/schemas/ImportExportTimeSeriesCost\",\"MARKET_BID_TIME_SERIES\":\"#/components/schemas/MarketBidTimeSeriesCost\"},\"propertyName\":\"cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/ImportExportCost\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/MarketBidTimeSeriesCost\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/ImportExportTimeSeriesCost\"}]},\"parameter_units\":{\"default\":\"COMPONENT_BASE\",\"description\":\"Unit basis for this source's impedance fields (R_th, X_th).\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_BASE\"],\"title\":\"ImpedanceUnitBasis\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"reactive_power\":{\"default\":0.0,\"description\":\"Initial reactive power set po