n\":\"Initial admittance at N = 0. Units: per admittance_units — NATURAL_UNITS: S, COMPONENT_MVAR: MVAr .\",\"properties\":{\"imag\":{\"type\":\"number\"},\"real\":{\"type\":\"number\"}},\"title\":\"ComplexNumber\",\"type\":\"object\",\"x-quantity\":\"Susceptance\",\"x-unit-discriminator\":\"admittance_units\",\"x-units\":{\"COMPONENT_MVAR\":\"MVAr\",\"NATURAL_UNITS\":\"S\"}},\"Y_increase\":{\"description\":\"Vector with admittance increment step for each adjustable shunt block. For example, `Y_increase[2]` is the complex admittance increment for each step at block 2. Units: per admittance_units — NATURAL_UNITS: S, COMPONENT_MVAR: MVAr .\",\"items\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/ComplexNumber\"},\"type\":\"array\",\"x-quantity\":\"Susceptance\",\"x-unit-discriminator\":\"admittance_units\",\"x-units\":{\"COMPONENT_MVAR\":\"MVAr\",\"NATURAL_UNITS\":\"S\"}},\"admittance_limits\":{\"default\":{\"max\":1.0,\"min\":1.0},\"description\":\"Shunt admittance limits for switched shunt model. Units: per admittance_units — NATURAL_UNITS: S, COMPONENT_MVAR: MVAr .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"Susceptance\",\"x-unit-discriminator\":\"admittance_units\",\"x-units\":{\"COMPONENT_MVAR\":\"MVAr\",\"NATURAL_UNITS\":\"S\"}},\"admittance_units\":{\"default\":\"COMPONENT_MVAR\",\"description\":\"Unit basis for the shunt admittance Y. COMPONENT_MVAR is PSS/E RAW native (Mvar/MW at unity voltage).\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_MVAR\"],\"title\":\"ShuntAdmittanceUnitBasis\",\"type\":\"string\"},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"bus\":{\"description\":\"ID of the bus that this component is connected to.\",\"type\":\"integer\"},\"control_mode\":{\"default\":\"FIXED\",\"description\":\"Switched-shunt control mode (PSS/E MODSW).\",\"enum\":[\"UNDEFINED\",\"FIXED\",\"DISCRETE_VOLTAGE\",\"CONTINUOUS_VOLTAGE\",\"DISCRETE_REACTIVE_PLANT\",\"DISCRETE_REACTIVE_VSC\",\"DISCRETE_ADMITTANCE_REMOTE\"],\"type\":\"string\"},\"dynamic_injector\":{\"description\":\"ID of the corresponding dynamic injection model for admittance, if any.\",\"type\":[\"integer\",\"null\"]},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"initial_status\":{\"description\":\"Vector of initial switched shunt status, one for in-service and zero for out-of-service for block i (1 through 8).\",\"items\":{\"type\":\"integer\"},\"type\":\"array\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"number_of_steps\":{\"description\":\"Vector with number of steps for each adjustable shunt block. For example, `number_of_steps[2]` are the number of available steps for admittance increment at block 2.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\"},\"regulated_bus_number\":{\"default\":0,\"description\":\"Bus number whose voltage/quantity this shunt regulates; 0 means local bus (PSS/E SWREM/NREG). Units: 1.\",\"type\":\"integer\",\"x-quantity\":\"Dimensionless\",\"x-unit\":\"1\"}},\"required\":[\"id\",\"name\",\"available\",\"bus\",\"Y\"],\"title\":\"SwitchedAdmittance\",\"type\":\"object\"},\"SynchronousCondenser\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A Synchronous Machine connected to the system to provide inertia or reactive power support.\",\"properties\":{\"active_power_losses\":{\"default\":0.0,\"description\":\"Active power loss incurred by having the unit online. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"base_power\":{\"description\":\"Base power of the unit for per unitization. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"bus\":{\"description\":\"ID of the bus that this component is connected to.\",\"type\":\"integer\"},\"dynamic_injector\":{\"description\":\"ID of the corresponding dynamic injection device, if any.\",\"type\":[\"integer\",\"null\"]},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"rating\":{\"description\":\"Maximum AC side output power rating of the unit. Not to be confused with base_power. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ApparentPower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"reactive_power\":{\"description\":\"Initial reactive power set point of the unit. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactiveP