ion. Must be positive; a zero base would make per-unit conversion undefined. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"bus\":{\"description\":\"ID of the bus that this component is connected to.\",\"type\":\"integer\"},\"commitment_mode\":{\"default\":\"COMMITTED\",\"description\":\"Commitment mode of the unit.\",\"enum\":[\"UNCOMMITTED\",\"COMMITTED\",\"SELF_SCHEDULED\",\"RELIABILITY\",\"MUST_RUN\"],\"title\":\"CommitmentModes\",\"type\":\"string\"},\"dynamic_injector\":{\"description\":\"ID of the corresponding dynamic injection device, if any.\",\"type\":[\"integer\",\"null\"]},\"fuel\":{\"default\":\"OTHER\",\"description\":\"Prime mover fuel according to EIA 923.\",\"enum\":[\"ANTHRACITE_COAL\",\"BITUMINOUS_COAL\",\"LIGNITE_COAL\",\"SUBBITUMINOUS_COAL\",\"WASTE_COAL\",\"REFINED_COAL\",\"SYNTHESIS_GAS_COAL\",\"DISTILLATE_FUEL_OIL\",\"JET_FUEL\",\"KEROSENE\",\"PETROLEUM_COKE\",\"RESIDUAL_FUEL_OIL\",\"PROPANE\",\"SYNTHESIS_GAS_PETROLEUM_COKE\",\"WASTE_OIL\",\"BLAST_FURNACE_GAS\",\"NATURAL_GAS\",\"OTHER_GAS\",\"AG_BYPRODUCT\",\"MUNICIPAL_WASTE\",\"OTHER_BIOMASS_SOLIDS\",\"WOOD_WASTE_SOLIDS\",\"OTHER_BIOMASS_LIQUIDS\",\"SLUDGE_WASTE\",\"BLACK_LIQUOR\",\"WOOD_WASTE_LIQUIDS\",\"LANDFILL_GAS\",\"OTHER_BIOMASS_GAS\",\"NUCLEAR\",\"WASTE_HEAT\",\"TIRE_DERIVED_FUEL\",\"COAL\",\"GEOTHERMAL\",\"OTHER\"],\"title\":\"ThermalFuels\",\"type\":\"string\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"operation_cost\":{\"description\":\"Operating cost of generation, or a MarketBidCost.\",\"discriminator\":{\"mapping\":{\"IMPORT_EXPORT_TIME_SERIES\":\"#/components/schemas/ImportExportTimeSeriesCost\",\"MARKET_BID\":\"#/components/schemas/MarketBidCost\",\"MARKET_BID_TIME_SERIES\":\"#/c