r\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"reactive_power\":{\"description\":\"Initial reactive power set point of the unit. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"reactive_power_limits\":{\"description\":\"Minimum and maximum reactive power limits. Set to `null` if not applicable. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"status\":{\"description\":\"Operating state of the unit at the start of a simulation.\",\"enum\":[\"OFFLINE\",\"STARTUP\",\"ONLINE\",\"SHUTDOWN\"],\"title\":\"OperationalStates\",\"type\":\"string\"},\"time_at_status\":{\"default\":600000.0,\"description\":\"Time the generator has been in its current status. Units: min.\",\"type\":\"number\",\"x-unit\":\"min\"},\"time_limits\":{\"description\":\"Minimum up and minimum down time limits. Units: min.\",\"properties\":{\"down\":{\"title\":\"Down\",\"type\":\"number\"},\"up\":{\"title\":\"Up\",\"type\":\"number\"}},\"required\":[\"up\",\"down\"],\"title\":\"UpDown\",\"type\":\"object\",\"x-unit\":\"min\"}},\"required\":[\"id\",\"name\",\"available\",\"status\",\"bus\",\"active_power\",\"reactive_power\",\"rating\",\"active_power_limits\",\"operation_cost\",\"base_power\",\"power_units\"],\"title\":\"ThermalStandard\",\"type\":\"object\"},\"ThreeWindingTransformer\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A three-winding transformer, modeled as an equivalent star: each referenced `TransformerCircuit` connects a terminal bus to the star (hidden) bus and carries that winding's series electrical data; availability is circuit-level. The pairwise measured impedances `r_12`/`x_12`, `r_23`/`x_23`, `r_31`/`x_31` (PSS/E CZ = 1, each in pu on the corresponding `base_power_12`/`base_power_23`/`base_power_31` and referenced to the first-index winding's base voltage) are optional and must be set together or all be absent; the star-leg impedances derived from them at parse time live on the circuits and are not synced back. Power-flow and Ybus assembly read the per-circuit star-leg impedances, not the pairwise fields. The model is described in Chapter 3.6 of J.D. Glover, M.S. Sarma and T. Overbye: Power Systems Analysis and Design.\",\"properties\":{\"admittance_units\":{\"default\":\"COMPONENT_BASE\",\"description\":\"Unit basis for the magnetizing_shunt admittance.\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_MVAR\",\"COMPONENT_BASE\"],\"title\":\"AdmittanceUnitBasis\",\"type\":\"string\"},\"base_power_12\":{\"description\":\"Base power for per unitization for primary-secondary windings. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"base_power_23\":{\"description\":\"Base power for per unitization for secondary-tertiary windings. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"base_power_31\":{\"description\":\"Base power for per unitization for tertiary-primary windings. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"magnetizing_shunt\":{\"default\":{\"imag\":0.0,\"real\":0.0},\"description\":\"Magnetizing shunt admittance referenced to the primary circuit's base voltage. Units: per admittance_units — NATURAL_UNITS: S, COMPONENT_MVAR: MVAr, COMPONENT_BASE: pu .\",\"properties\":{\"imag\":{\"type\":\"number\"},\"real\":{\"type\":\"number\"}},\"title\":\"ComplexNumber\",\"type\":\"object\",\"x-quantity\":\"Susceptance\",\"x-unit-discriminator\":\"admittance_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"COMPONENT_MVAR\":\"MVAr\",\"NATURAL_UNITS\":\"S\"}},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"parameter_units\":{\"default\":\"COMPONENT_BASE\",\"description\":\"Unit basis for the pairwise measured impedance fields (r_12, x_12, r_23, x_23, r_31, x_31). PSS/E supplies a single CZ flag for the whole three-winding transformer record, so one basis governs all three winding pairs.\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_BASE\"],\"title\":\"ImpedanceUnitBasis\",\"type\":\"string\"},\"primary_circuit\":{\"description\":\"The primary `TransformerCircuit` connecting the primary bus to the star bus.\",\"type\":\"integer\"},\"r_12\":{\"description\":\"Measured resistance, referenced to the primary winding's base voltage, from primary to secondary windings (R1-2 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Resistance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"r_23\":{\"description\":\"Measured resistance, referenced to the secondary winding's base voltage, from secondary to tertiary windings (R2-3 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Resistance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"r_31\":{\"description\":\"Measured resistance, referenced to the tertiary winding's base voltage, from tertiary to primary windings (R3-1 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Resistance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"secondary_circuit\":{\"description\":\"The secondary `TransformerCircuit` connecting the secondary bus to the star bus.\",\"type\":\"integer\"},\"shunt_location\":{\"default\":\"PRIMARY\",\"description\":\"Placement of `magnetizing_shunt` in the equivalent star model.\",\"enum\":[\"PRIMARY\",\"STAR\"],\"title\":\"ThreeWindingTransformerShuntLocation\",\"type\":\"string\"},\"star_bus\":{\"description\":\"Star (hidden) Bus that this component (equivalent model) is connected to.\",\"type\":\"integer\"},\"tertiary_circuit\":{\"description\":\"The tertiary `TransformerCircuit` connecting the tertiary bus to the star bus.\",\"type\":\"integer\"},\"x_12\":{\"description\":\"Measured reactance, referenced to the primary winding's base voltage, from primary to secondary windings (X1-2 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Reactance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"x_23\":{\"description\":\"Measured reactance, referenced to the secondary winding's base voltage, from secondary to tertiary windings (X2-3 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Reactance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"x_31\":{\"description\":\"Measured reactance, referenced to the tertiary winding's base voltage, from tertiary to primary windings (X3-1 in PSS/E). Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Reactance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}}},\"required\":[\"id\",\"name\",\"primary_circuit\",\"secondary_circuit\",\"tertiary_circuit\",\"star_bus\"],\"title\":\"ThreeWindingTransformer\",\"type\":\"object\"},\"ThreeWindingTransformerShuntLocation\":{\"description\":\"Placement of a `ThreeWindingTransformer`'s magnetizing shunt admittance in the equivalent star model. PRIMARY: the full magnetizing shunt is applied on the winding-1 (primary) terminal side. STAR: the full magnetizing shunt is applied at the star node.\",\"enum\":[\"PRIMARY\",\"STAR\"],\"title\":\"ThreeWindingTransformerShuntLocation\",\"type\":\"string\"},\"TimeSeriesAverageRateCurve\":{\"description\":\"A time-series-backed average rate curve. The static counterpart is AverageRateCurve.\",\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_AVERAGE_RATE\",\"default\":\"TIME_SERIES_AVERAGE_RATE\",\"type\":\"string\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR or TIME_SERIES_PIECEWISE_STEP is admissible here; all other FunctionData variants, static or time-series-backed, are rejected by the consuming constructor.\"},\"initial_input_association_id\":{\"description\":\"Store-minted id of the time series supplying the initial input value, or null.\",\"type\":[\"integer\",\"null\"]},\"input_at_zero_association_id\":{\"description\":\"Store-minted id of the time series supplying the input at zero output, or null.\",\"type\":[\"integer\",\"null\"]}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"TimeSeriesAverageRateCurve\",\"type\":\"object\"},\"TimeSeriesIncrementalCurve\":{\"description\":\"A time-series-backed incremental curve. The static counterpart is IncrementalCurve.\",\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_INCREMENTAL\",\"default\":\"TIME_SERIES_INCREMENTAL\",\"type\":\"string\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR or TIME_SERIES_PIECEWISE_STEP is admissible here; all other FunctionData variants, static or time-series-backed, are rejected by the consuming constructor.\"},\"initial_input_association_id\":{\"description\":\"Store-minted id of the time series supplying the initial input value, or null.\",\"type\":[\"integer\",\"null\"]},\"input_at_zero_association_id\":{\"description\":\"Store-minted id of the time series supplying the input at zero output, or null.\",\"type\":[\"integer\",\"null\"]}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"TimeSeriesIncrementalCurve\",\"type\":\"object\"},\"TimeSeriesInputOutputCurve\":{\"description\":\"A time-series-backed input-output curve. The static counterpart is InputOutputCurve.\",\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_INPUT_OUTPUT\",\"default\":\"TIME_SERIES_INPUT_OUTPUT\",\"type\":\"string\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR, TIME_SERIES_QUADRATIC, or TIME_SERIES_PIECEWISE_LINEAR is admissible here; the static variants and TIME_SERIES_PIECEWISE_STEP are invalid and rejected by the consuming constructor.\"},\"input_at_zero\":{\"description\":\"Optional explicit input value at zero output. A number here, unlike the incremental and average-rate variants, where it is a time series reference.\",\"type\":[\"number\",\"null\"]}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"TimeSeriesInputOutputCurve\",\"type\":\"object\"},\"TimeSeriesLinearFunctionData\":{\"description\":\"Time-series-backed variant of `LinearFunctionData`. In place of inline coefficients it carries `association_id`, referencing a stored series that supplies them at each step; use it when the coefficients change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_LINEAR\",\"default\":\"TIME_SERIES_LINEAR\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesLinearFunctionData\",\"type\":\"object\"},\"TimeSeriesPiecewiseLinearData\":{\"description\":\"Time-series-backed variant of `PiecewiseLinearData`. In place of an inline point table it carries `association_id`, referencing a stored series that supplies one at each step; use it when the points change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_PIECEWISE_LINEAR\",\"default\":\"TIME_SERIES_PIECEWISE_LINEAR\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesPiecewiseLinearData\",\"type\":\"object\"},\"TimeSeriesPiecewiseStepData\":{\"description\":\"Time-series-backed variant of `PiecewiseStepData`. In place of inline coordinate vectors it carries `association_id`, referencing a stored series that supplies them at each step; use it when the segments change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_PIECEWISE_STEP\",\"default\":\"TIME_SERIES_PIECEWISE_STEP\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesPiecewiseStepData\",\"type\":\"object\"},\"TimeSeriesQuadraticFunctionData\":{\"description\":\"Time-series-backed variant of `QuadraticFunctionData`. In place of inline coefficients it carries `association_id`, referencing a stored series that supplies them at each step; use it when the coefficients change over time.\",\"properties\":{\"association_id\":{\"description\":\"Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.\",\"type\":\"integer\"},\"function_type\":{\"const\":\"TIME_SERIES_QUADRATIC\",\"default\":\"TIME_SERIES_QUADRATIC\",\"type\":\"string\"}},\"required\":[\"function_type\",\"association_id\"],\"title\":\"TimeSeriesQuadraticFunctionData\",\"type\":\"object\"},\"TradingHub\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A market trading hub: a named set of member buses at which hub-settled bids are priced. Membership is carried as TradingHubAssociation rows rather than a list on this record, matching the service-membership convention.\",\"properties\":{\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the hub.\",\"type\":\"string\"}},\"required\":[\"id\",\"name\"],\"title\":\"TradingHub\",\"type\":\"object\"},\"TradingHubAssociation\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Links a trading hub to one associated entity. One record per (hub, member) pair. `entity_id` may name a bus (hub membership) or a market transaction settling at the hub, resolved through the entity registry, so no member-type discriminator is needed — the same shape as ServiceAssociation.\",\"properties\":{\"entity_id\":{\"description\":\"ID of the associated entity: a bus or a market transaction.\",\"type\":\"integer\"},\"trading_hub_id\":{\"description\":\"ID of the trading hub the association belongs to.\",\"type\":\"integer\"}},\"required\":[\"trading_hub_id\",\"entity_id\"],\"title\":\"TradingHubAssociation\",\"type\":\"object\"},\"TransformerCircuit\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"The data defining one modeled arc of a transformer.\\n\\nA `TwoWindingTransformer` has one circuit; a `ThreeWindingTransformer` has three, each connecting a terminal bus to the star bus. Circuit `available` is the single source of truth for availability; the owning transformer derives its availability from its circuits. `r`/`x` are the circuit impedance (for a two-winding transformer, the series impedance; for a three-winding transformer, the star-leg equivalent), in pu (device base) on `base_power` referenced to `base_voltage_primary`. Tap-changer / phase-shifter control is described by the flat control fields: `control_objective = UNDEFINED` means the circuit has no control block. For a `TwoWindingTransformer`, the single circuit's `base_power` is the transformer's device base.\",\"properties\":{\"active_power_flow\":{\"default\":0.0,\"description\":\"Initial condition of active power flow through this circuit. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"alpha\":{\"default\":0.0,\"description\":\"Initial condition of phase shift across this circuit. Units: rad.\",\"type\":\"number\",\"x-unit\":\"rad\"},\"arc\":{\"description\":\"An `Arc` defining this circuit `from` a terminal bus `to` the transformer's other terminal or star bus.\",\"type\":\"integer\"},\"available\":{\"description\":\"Indicator of whether this circuit is connected and online.\",\"type\":\"boolean\"},\"base_power\":{\"default\":100.0,\"description\":\"Base power for per unitization of this circuit. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"base_voltage_primary\":{\"description\":\"Primary (from) terminal-side base voltage; the reference voltage for this circuit's per-unit impedance. Units: kV.\",\"type\":\"number\",\"x-unit\":\"kV\"},\"base_voltage_secondary\":{\"description\":\"Secondary (to) terminal-side base voltage. For a three-winding transformer this defaults to the primary base voltage at parse time. Units: kV.\",\"type\":\"number\",\"x-unit\":\"kV\"},\"control_limits\":{\"default\":{\"max\":1.1,\"min\":0.9},\"description\":\"Control band (PSS/E RMA/RMI), per `control_objective`. Units: per control_objective — UNDEFINED: 1, VOLTAGE_DISABLED: 1, REACTIVE_POWER_FLOW_DISABLED: 1, ACTIVE_POWER_FLOW_DISABLED: rad, CONTROL_OF_DC_LINE_DISABLED: 1, ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED: rad, FIXED: 1, VOLTAGE: 1, REACTIVE_POWER_FLOW: 1, ACTIVE_POWER_FLOW: rad, CONTROL_OF_DC_LINE: 1, ASYMMETRIC_ACTIVE_POWER_FLOW: rad .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"Dimensionless\",\"x-unit-discriminator\":\"control_objective\",\"x-units\":{\"ACTIVE_POWER_FLOW\":\"rad\",\"ACTIVE_POWER_FLOW_DISABLED\":\"rad\",\"ASYMMETRIC_ACTIVE_POWER_FLOW\":\"rad\",\"ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED\":\"rad\",\"CONTROL_OF_DC_LINE\":\"1\",\"CONTROL_OF_DC_LINE_DISABLED\":\"1\",\"FIXED\":\"1\",\"REACTIVE_POWER_FLOW\":\"1\",\"REACTIVE_POWER_FLOW_DISABLED\":\"1\",\"UNDEFINED\":\"1\",\"VOLTAGE\":\"1\",\"VOLTAGE_DISABLED\":\"1\"}},\"control_objective\":{\"default\":\"UNDEFINED\",\"description\":\"Tap-changer / phase-shifter control objective (PSS/E COD). `UNDEFINED` means this circuit has no control block.\",\"enum\":[\"UNDEFINED\",\"VOLTAGE_DISABLED\",\"REACTIVE_POWER_FLOW_DISABLED\",\"ACTIVE_POWER_FLOW_DISABLED\",\"CONTROL_OF_DC_LINE_DISABLED\",\"ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED\",\"FIXED\",\"VOLTAGE\",\"REACTIVE_POWER_FLOW\",\"ACTIVE_POWER_FLOW\",\"CONTROL_OF_DC_LINE\",\"ASYMMETRIC_ACTIVE_POWER_FLOW\"],\"title\":\"TransformerControlObjective\",\"type\":\"string\"},\"controlled_quantity_limits\":{\"default\":{\"max\":1.1,\"min\":0.9},\"description\":\"Controlled-quantity band (PSS/E VMA/VMI), per `control_objective`. Units: per control_objective — UNDEFINED: pu, VOLTAGE_DISABLED: pu, REACTIVE_POWER_FLOW_DISABLED: MVAr, ACTIVE_POWER_FLOW_DISABLED: MW, CONTROL_OF_DC_LINE_DISABLED: MW, ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED: MW, FIXED: pu, VOLTAGE: pu, REACTIVE_POWER_FLOW: MVAr, ACTIVE_POWER_FLOW: MW, CONTROL_OF_DC_LINE: MW, ASYMMETRIC_ACTIVE_POWER_FLOW: MW .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"Voltage\",\"x-unit-discriminator\":\"control_objective\",\"x-units\":{\"ACTIVE_POWER_FLOW\":\"MW\",\"ACTIVE_POWER_FLOW_DISABLED\":\"MW\",\"ASYMMETRIC_ACTIVE_POWER_FLOW\":\"MW\",\"ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED\":\"MW\",\"CONTROL_OF_DC_LINE\":\"MW\",\"CONTROL_OF_DC_LINE_DISABLED\":\"MW\",\"FIXED\":\"pu\",\"REACTIVE_POWER_FLOW\":\"MVAr\",\"REACTIVE_POWER_FLOW_DISABLED\":\"MVAr\",\"UNDEFINED\":\"pu\",\"VOLTAGE\":\"pu\",\"VOLTAGE_DISABLED\":\"pu\"}},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"number_of_tap_positions\":{\"default\":33,\"description\":\"Number of tap positions (PSS/E NTP).\",\"type\":\"integer\"},\"parameter_units\":{\"default\":\"COMPONENT_BASE\",\"description\":\"Unit basis for this circuit's impedance fields (r, x).\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_BASE\"],\"title\":\"ImpedanceUnitBasis\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"r\":{\"default\":0.0,\"description\":\"Circuit resistance. Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Resistance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"rating\":{\"description\":\"Thermal rating. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ApparentPower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"rating_b\":{\"description\":\"Second current rating. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ApparentPower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"rating_c\":{\"description\":\"Third current rating. Units: per power_units — NATURAL_UNITS: MVA, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ApparentPower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVA\"}},\"reactive_power_flow\":{\"default\":0.0,\"description\":\"Initial condition of reactive power flow through this circuit. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"regulated_bus_number\":{\"default\":0,\"description\":\"Controlled bus number (PSS/E CONT; sign = regulation side).\",\"type\":\"integer\"},\"tap\":{\"default\":1.0,\"description\":\"Normalized tap changer position for voltage control, varying between 0 and 2, with 1 centered at the nominal voltage. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Dimensionless\",\"x-unit\":\"1\"},\"x\":{\"default\":0.0,\"description\":\"Circuit reactance. Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Reactance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}}},\"required\":[\"id\",\"available\",\"arc\",\"power_units\"],\"title\":\"TransformerCircuit\",\"type\":\"object\"},\"TransformerControlObjective\":{\"description\":\"Control objective of a transformer tap changer or phase shifter: a fixed tap position with no automatic adjustment (`FIXED`), or regulation of voltage magnitude at the controlled bus, reactive power flow, active power flow, asymmetric active power flow, or a DC line. Each regulating objective has a paired `_DISABLED` value naming the same control block while it is out of service, and `UNDEFINED` means no control objective is stated.\",\"enum\":[\"UNDEFINED\",\"VOLTAGE_DISABLED\",\"REACTIVE_POWER_FLOW_DISABLED\",\"ACTIVE_POWER_FLOW_DISABLED\",\"CONTROL_OF_DC_LINE_DISABLED\",\"ASYMMETRIC_ACTIVE_POWER_FLOW_DISABLED\",\"FIXED\",\"VOLTAGE\",\"REACTIVE_POWER_FLOW\",\"ACTIVE_POWER_FLOW\",\"CONTROL_OF_DC_LINE\",\"ASYMMETRIC_ACTIVE_POWER_FLOW\"],\"title\":\"TransformerControlObjective\",\"type\":\"string\"},\"TransmissionInterface\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A collection of transmission branches whose combined flow is monitored and constrained as an interface.\",\"properties\":{\"active_power_flow_limits\":{\"description\":\"Minimum and maximum active power flow limits on the interface. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"base_power\":{\"description\":\"System base power for per-unitization of this component's per-unit fields, recorded per component in lieu of a system-level table. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"direction_mapping\":{\"additionalProperties\":{\"type\":\"integer\"},\"description\":\"Dictionary of the line `name`s in the interface and their direction of flow (1 or -1) relative to the flow of the interface.\",\"type\":\"object\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"violation_penalty\":{\"description\":\"Penalty cost for violating the flow limits in the interface.\",\"type\":\"number\"}},\"required\":[\"id\",\"name\",\"available\",\"active_power_flow_limits\",\"base_power\",\"power_units\"],\"title\":\"TransmissionInterface\",\"type\":\"object\"},\"TwoTerminalGenericHVDCLine\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"A High Voltage DC line, which must be connected to an ACBus on each end. This model is appropriate for operational simulations with a linearized DC power flow approximation with losses proportional to the power flow. For modeling a DC network, see TModelHVDCLine.\",\"properties\":{\"active_power_flow\":{\"description\":\"Initial condition of active power flow on the line. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"active_power_limits_from\":{\"description\":\"Minimum and maximum active power flows to the FROM node. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"active_power_limits_to\":{\"description\":\"Minimum and maximum active power flows to the TO node. Units: per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ActivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MW\"}},\"arc\":{\"description\":\"An Arc defining this line `from` a bus `to` another bus.\",\"type\":\"integer\"},\"available\":{\"description\":\"Indicator of whether the component is connected and online (`true`) or disconnected, offline, or down (`false`). Unavailable components are excluded during simulations.\",\"type\":\"boolean\"},\"base_power\":{\"description\":\"System base power for per-unitization of this component's per-unit fields, recorded per component in lieu of a system-level table. Units: MVA.\",\"type\":\"number\",\"x-unit\":\"MVA\"},\"id\":{\"description\":\"Unique integer identifier for this component.\",\"type\":\"integer\"},\"loss\":{\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"constant_term\":0,\"function_type\":\"LINEAR\",\"proportional_term\":0}},\"description\":\"Loss model coefficients. It accepts a linear model with a constant loss and a proportional loss rate (MW of loss per MW of flow). It also accepts a Piecewise loss, with N segments to specify different proportional losses for different segments.\",\"discriminator\":{\"mapping\":{\"INCREMENTAL\":\"#/components/schemas/IncrementalCurve\",\"INPUT_OUTPUT\":\"#/components/schemas/InputOutputCurve\"},\"propertyName\":\"curve_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/InputOutputCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/root-1068b1dda553e6e25b3b.json#/components/schemas/IncrementalCurve\"}],\"title\":\"TwoTerminalLoss\",\"type\":\"object\"},\"name\":{\"description\":\"Name of the component. Components of the same type (e.g., `PowerLoad`) must have unique names, but components of different types (e.g., `PowerLoad` and `ACBus`) can have the same name.\",\"type\":\"string\"},\"power_units\":{\"description\":\"Unit basis for this component's power-family fields (active/reactive/apparent power, ratings, limits, ramp rates). COMPONENT_BASE: per unit on this component's own base_power. NATURAL_UNITS: the field's physical unit.\",\"enum\":[\"COMPONENT_BASE\",\"NATURAL_UNITS\"],\"title\":\"UnitSystem\",\"type\":\"string\"},\"reactive_power_limits_from\":{\"description\":\"Minimum and maximum reactive power limits to the FROM node. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"ReactivePower\",\"x-unit-discriminator\":\"power_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"MVAr\"}},\"reactive_power_limits_to\":{\"description\":\"Minimum and maximum reactive power limits to the TO node. Units: per power_units — NATURAL_UNITS: MVAr, COMPONENT_BASE: pu .\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"M