ude per bridge. Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Reactance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"inverter_extinction_angle\":{\"default\":0.0,\"description\":\"Inverter extinction angle (gamma). Units: rad.\",\"type\":\"number\",\"x-unit\":\"rad\"},\"inverter_extinction_angle_limits\":{\"description\":\"Minimum and maximum inverter extinction angle (gamma). Units: rad.\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-unit\":\"rad\"},\"inverter_rc\":{\"description\":\"Inverter commutating transformer resistance per bridge. Units: per parameter_units — NATURAL_UNITS: ohm, COMPONENT_BASE: pu .\",\"type\":\"number\",\"x-quantity\":\"Resistance\",\"x-unit-discriminator\":\"parameter_units\",\"x-units\":{\"COMPONENT_BASE\":\"pu\",\"NATURAL_UNITS\":\"ohm\"}},\"inverter_tap_limits\":{\"default\":{\"max\":1.5,\"min\":0.51},\"description\":\"Minimum and maximum inverter tap limits as a ratio between the primary and secondary side AC voltages. Units: 1.\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\",\"x-quantity\":\"Dimensionless\",\"x-unit\":\"1\"},\"inverter_tap_setting\":{\"default\":1.0,\"description\":\"Inverter transformer tap setting. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Dimensionless\",\"x-unit\":\"1\"},\"inverter_tap_step\":{\"default\":0.00625,\"description\":\"Inverter transformer tap step value. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Dimensionless\",\"x-unit\":\"1\"},\"inverter_transformer_ratio\":{\"default\":1.0,\"description\":\"Inverter transformer ratio between the primary and secondary side AC voltages. Units: 1.\",\"type\":\"number\",\"x-quantity\":\"Dimensionless\",\"x